package dev.cazajefes;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
import org.bukkit.util.Vector;
public class PillagerRulesTest {
 @Test public void enchantedCrossbowHasExactRequestedLevels(){assertEquals(Integer.valueOf(10),PillagerRules.ENCHANTMENTS.get("quick_charge"));assertEquals(Integer.valueOf(15),PillagerRules.ENCHANTMENTS.get("multishot"));assertEquals(Integer.valueOf(10),PillagerRules.ENCHANTMENTS.get("unbreaking"));assertEquals(Integer.valueOf(10),PillagerRules.ENCHANTMENTS.get("knockback"));assertEquals(Integer.valueOf(1),PillagerRules.ENCHANTMENTS.get("infinity"));assertEquals(Integer.valueOf(1),PillagerRules.ENCHANTMENTS.get("mending"));assertEquals(Integer.valueOf(10),PillagerRules.ENCHANTMENTS.get("piercing"));}
 @Test public void thirtyArrowFanHasCenteredNormalizedDirections(){var forward=new Vector(0,.2,1);var original=forward.clone();var fan=PillagerRules.fan(forward);assertEquals(30,fan.size());assertEquals(original,forward);Set<String> unique=new HashSet<>();for(var v:fan){assertEquals(1,v.length(),.00001);assertTrue(unique.add(v.toString()));}assertTrue(fan.get(0).dot(forward.clone().normalize())>.9999);}
 @Test public void retaliationRequiresFiveRecentHitsAndConsumesCharge(){var hits=new PillagerRules.Hits(5);for(int i=0;i<4;i++){hits.add(i*100);assertFalse(hits.charged(i*100));}hits.add(400);assertTrue(hits.charged(400));hits.consume();assertFalse(hits.charged(500));for(int i=0;i<5;i++)hits.add(1000+i);assertFalse(hits.charged(10000));}
 @Test public void diagonalBurstKeepsVerticalMechanism(){assertEquals(1.25,CombatPower.ASCENT_LATERAL,0);assertTrue(CombatPower.ASCENT_LATERAL>.35);assertTrue(BurstLaunch.sustainedLift(StageAttackRules.lift(1)));assertEquals(2.65,StageAttackRules.lift(3),.00001);}
 @Test public void oneChargeProducesSixBurstsOfThirty(){var burst=new PillagerRules.Burst();burst.start(1000);int salvos=0;for(int i=0;i<6;i++){assertTrue(burst.take(1000+i*250));salvos++;assertFalse(burst.take(1000+i*250));}assertFalse(burst.active());assertFalse(burst.take(99999));assertEquals(180,salvos*PillagerRules.VOLLEY_SIZE);}
 @Test public void predictionLeadsAnAscendingAndLateralTarget(){Vector from=new Vector(0,1,0),target=new Vector(0,8,20),velocity=new Vector(.5,1,.1);var direction=PillagerRules.aim(from,target,velocity,3.2,10,true);assertTrue(direction.getX()>0);assertTrue(direction.getY()>target.clone().subtract(from).normalize().getY());assertEquals(1,direction.length(),.00001);assertEquals(new Vector(.5,1,.1),velocity);assertTrue(PillagerRules.arrowDrop(10)>0);}
 @Test public void verticalTargetStillHasThirtyDistinctArrowPaths(){Set<String> unique=new HashSet<>();for(var direction:PillagerRules.fan(new Vector(0,1,0))){assertEquals(1,direction.length(),.00001);assertTrue(unique.add(direction.toString()));}assertEquals(30,unique.size());}
 @Test public void ballisticLeadApproachesMovingAirTargetInOpenSpace(){Vector from=new Vector(0,2,0),target=new Vector(10,10,18),motion=new Vector(.2,.6,.1);Vector position=from.clone(),arrow=PillagerRules.aim(from,target,motion,3.2,10,true).multiply(3.2);double nearest=Double.POSITIVE_INFINITY;for(int tick=1;tick<=20;tick++){position.add(arrow);arrow.multiply(.99).setY(arrow.getY()-.05);nearest=Math.min(nearest,position.distance(PillagerRules.predict(target,motion,tick,10,true)));}assertTrue("distancia="+nearest,nearest<1.5);}
}
